from PIL import Image
def bore_center(f):
    im=Image.open("/home/robot/captures/"+f).convert("L")
    w,h=im.size; px=im.load()
    best=None
    for y in range(30,h-30,2):
        for x in range(30,w-30,2):
            if px[x,y]<60:
                # check annulus r=16-20 for light
                ok=True; s=0
                for a in range(0,360,30):
                    import math
                    xx=int(x+19*math.cos(math.radians(a))); yy=int(y+19*math.sin(math.radians(a)))
                    if px[xx,yy]<120: ok=False; break
                if ok:
                    # refine centroid of dark pixels in 15px box
                    sx=sy=n=0
                    for dy in range(-15,16):
                        for dx in range(-15,16):
                            if px[x+dx,y+dy]<60: sx+=dx; sy+=dy; n+=1
                    return (x+sx/n, y+sy/n)
    return best
for f in ["wrist_002.png","wrist_003.png","wrist_004.png"]:
    print(f, bore_center(f))
EOF

