import workcell
cx,cy=400.68,268.79
step=0.04
# spiral
pts=[(0,0)]
for r in range(1,6):
    for dx in range(-r,r+1):
        for dy in range(-r,r+1):
            if max(abs(dx),abs(dy))==r:
                pts.append((dx,dy))
for dx,dy in pts:
    x=cx+dx*step; y=cy+dy*step
    r=workcell.call("robot","insert",str(round(x,2)),str(round(y,2)))
    if r.ok:
        print("SEATED at",x,y,"offset",dx*step,dy*step); break
else:
    print("not found")
EOF

